//go:build flags

package main

// The pride-flag palettes, built only with -tags flags.
//
// Out of the debug build's default image on purpose: 10 flags x 36 LEDs x 4 bytes
// is 1,440 bytes of flash - about five times what the beat-tracking work needs to
// fit - and the debug branch exists to measure the audio pipeline, not to look at
// flags. The mode itself stays in the mode list so the stored-mode numbering does
// not shift (see the note in flags_off.go about why that matters across branches);
// with the tables absent, showFlag renders black.
//
//	tinygo build -tags flags -o firmware.hex -target=./stm32l0x1.json -opt=2
//
// Master still builds these unconditionally and is where any change to this data
// has to be re-checked for size.

// Palette is one flag: 36 packed Color values in a string.
type Palette string

func (p Palette) color(i int) Color {
	_ = p[4*i+3] // bounds check hint; four bytes per LED
	return Color(p[4*i]) | Color(p[4*i+1])<<8 | Color(p[4*i+2])<<16 | Color(p[4*i+3])<<24
}

